// Custom Cloudflare Worker entry: the OpenNext-generated Next.js worker plus a
// `scheduled` handler for the cron triggers in wrangler.jsonc. Each cron calls
// the protected /api/cron/<job> route on the same worker.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
  [key: string]: unknown;
}

const JOBS_BY_CRON: Record<string, string[]> = {
  "*/15 * * * *": ["showroom-sweep"],
  "*/30 * * * *": ["orphan-uploads"],
  "0 6 * * *": ["cazoo-health"],
};

export default {
  fetch: handler.fetch,

  async scheduled(
    event: { cron: string },
    env: Env,
    ctx: { waitUntil(p: Promise<unknown>): void },
  ): Promise<void> {
    const jobs = JOBS_BY_CRON[event.cron] ?? [];
    for (const job of jobs) {
      const req = new Request(`https://cron.internal/api/cron/${job}`, {
        headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
      });
      ctx.waitUntil(
        handler.fetch(req, env, ctx).then(async (res: Response) => {
          console.log(JSON.stringify({ level: "info", msg: "cron job finished", job, status: res.status, body: await res.text() }));
        }),
      );
    }
  },
};
